// Package generated renders the harness-neutral parts of tenon-owned files.
// Generated files are visibly tool-owned and disposable; the marker is the
// visible ownership claim, not an enforcement mechanism.
package generated

import (
	"fmt"
	"strings"
	"unicode"
)

// Marker is the first line of every tenon-owned Markdown file.
const Marker = "<!-- Generated by tenon apply; do not edit. Edit the agent source and reapply. -->"

// TOMLHeader is Marker's sentence in TOML comment form: the first line of
// every tenon-owned TOML file that permits comments. Like Marker it carries
// no fingerprint, version, or provenance.
const TOMLHeader = "# Generated by tenon apply; do not edit. Edit the agent source and reapply."

// MaxMCPConfigBytes bounds one generated native MCP configuration file —
// Claude's .mcp.json and Codex's .codex/config.toml (ADR 0013). The rendered
// file is measured before any workspace mutation.
const MaxMCPConfigBytes = 8 << 20

// Instructions renders an always-on instructions file: the ownership marker
// followed by the authored body, never the frontmatter.
func Instructions(body string) []byte {
	body = strings.TrimRight(body, "\n")
	return []byte(Marker + "\n\n" + body + "\n")
}

// SkillMD renders a generated SKILL.md: the authored bytes with the
// ownership marker inserted as one line immediately after the closing
// frontmatter delimiter line at bodyStart, and no other change. The marker
// deliberately carries no fingerprint, version, or provenance: setup
// metadata never enters model-facing generated content.
func SkillMD(source []byte, bodyStart int) []byte {
	out := make([]byte, 0, len(source)+len(Marker)+2)
	out = append(out, source[:bodyStart]...)
	if bodyStart == 0 || source[bodyStart-1] != '\n' {
		out = append(out, '\n')
	}
	out = append(out, Marker...)
	out = append(out, '\n')
	out = append(out, source[bodyStart:]...)
	return out
}

// YAMLString renders s as one valid YAML double-quoted scalar, including the
// surrounding quotes — valid YAML output, not Go syntax. Backslash and
// double quote are escaped; \n, \t, and \r use their native short escapes;
// any other Unicode control character uses a two-digit \xHH escape; and
// printable non-ASCII text stays literal.
func YAMLString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		case '\n':
			b.WriteString(`\n`)
		case '\t':
			b.WriteString(`\t`)
		case '\r':
			b.WriteString(`\r`)
		default:
			if unicode.IsControl(r) {
				fmt.Fprintf(&b, `\x%02X`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// TOMLString renders s as one valid TOML v1 basic string, including the
// surrounding quotes — valid TOML output, not Go syntax, so strconv.Quote is
// never used (Go escapes such as \a and \xHH are not valid TOML). Backslash
// and double quote are escaped; \n, \t, and \r use their native short
// escapes; any other Unicode control character uses a four-digit \u00HH
// escape; and printable non-ASCII text stays literal.
func TOMLString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		case '\n':
			b.WriteString(`\n`)
		case '\t':
			b.WriteString(`\t`)
		case '\r':
			b.WriteString(`\r`)
		default:
			if unicode.IsControl(r) {
				fmt.Fprintf(&b, `\u%04X`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// ClaudeSubagent renders one native Claude subagent file (ADR 0004, amended
// by ADR 0007): closed frontmatter carrying only the child's own routing
// metadata — name, description, and, when set, effort — followed by the
// whitespace-trimmed body. It never carries the parent's instructions,
// skills, or tools: native inheritance supplies those. name is the portable
// hyphenated subagent name, used unquoted since the subagent name grammar
// never needs YAML quoting. effort is "" when absent, omitting the line
// entirely rather than emitting it empty.
func ClaudeSubagent(name, description, effort, body string) []byte {
	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString("name: " + name + "\n")
	b.WriteString("description: " + YAMLString(description) + "\n")
	if effort != "" {
		b.WriteString("effort: " + effort + "\n")
	}
	b.WriteString("---\n\n")
	b.WriteString(strings.TrimSpace(body))
	b.WriteString("\n")
	return []byte(b.String())
}

// CodexSubagent renders one native Codex custom-agent TOML file (ADR 0004,
// amended by ADR 0007). The name value converts the portable hyphenated name
// to Codex's underscored collaboration identifier rule; the caller keeps the
// hyphenated name in the generated file's path. effort is "" when absent,
// omitting model_reasoning_effort entirely rather than emitting it empty.
func CodexSubagent(name, description, effort, body string) []byte {
	var b strings.Builder
	b.WriteString("name = " + TOMLString(strings.ReplaceAll(name, "-", "_")) + "\n")
	b.WriteString("description = " + TOMLString(description) + "\n")
	if effort != "" {
		b.WriteString("model_reasoning_effort = " + TOMLString(effort) + "\n")
	}
	b.WriteString("developer_instructions = " + TOMLString(strings.TrimSpace(body)) + "\n")
	return []byte(b.String())
}
